// Ads Payment Center — provider layer. Three jobs, each behind its own adapter:
//   extract  — ask the SOURCE for a Fawry code that tops up an ad account
//   pay      — settle an already-issued code from a wallet / payment method
//   credit   — confirm that Meta credited that specific code to the ad account («تسميع»)
//
// THE HONEST STATE (verified 2026-11-25, see the capability report in the screen):
//   • Meta's Marketing API has no endpoint that issues a Fawry code for adding funds — the code is generated by Meta's billing UI (Ads Manager → Billing → Add funds → Fawry).
//   • Fawry's APIs (FawryPay / «PayAtFawry») are MERCHANT collection APIs: they create a reference so a customer can pay the MERCHANT. They do not pay a reference that Meta issued,
//     and a partner/biller agreement with Fawry is needed for anything beyond that.
//   • Nothing official lets us prove a SPECIFIC code was credited; a balance that went up is only a hint (spend also moves it), never proof.
// So no real adapter is registered. Every function below reports «تحتاج ربط» and the screen falls back to MANUAL registration (the owner pastes the code from Ads Manager, pays it from Fawry /
// a wallet, and records the transaction number + receipt) — a human attests, and the system tracks, de-duplicates, audits and reconciles it.
// A real adapter plugs in with registerProvider('extract'|'pay'|'credit', impl) the day an official contract exists; the engine does not change.
//
// SIMULATION exists ONLY on the isolated test database (TEST_DB_GUARD) or under NODE_ENV=test, and only when ADS_PAYMENTS_SIMULATION=1: it can never run on production data.
import crypto from 'node:crypto';

const registry = { extract: null, pay: null, credit: null };
export function registerProvider(kind, impl) { if (!(kind in registry)) throw new Error('unknown provider kind'); registry[kind] = impl; }
export function _resetProviders() { for (const k of Object.keys(registry)) registry[k] = null; sim.behavior = {}; sim.paid.clear(); }

export const simulationAllowed = () => process.env.ADS_PAYMENTS_SIMULATION === '1' && (process.env.TEST_DB_GUARD === '1' || process.env.NODE_ENV === 'test') && process.env.NODE_ENV !== 'production';

const NEEDS = {
  extract: { label: 'استخراج كود فوري', reason: 'مفيش واجهة رسمية من Meta بتطلّع كود فوري لشحن الحساب — الكود بيتولّد من Ads Manager (الفوترة ← إضافة أموال ← فوري). الاستخراج الآلي محتاج اتفاق رسمي مع Meta/فوري.', manual: 'افتح Ads Manager، اطلب الكود من «إضافة أموال»، وسجّله هنا بـ «تسجيل كود».' },
  pay: { label: 'الدفع المباشر لكود فوري', reason: 'واجهات فوري الرسمية (FawryPay) مخصصة لتحصيل التاجر مش لسداد كود صادر من Meta، وسداد أكواد طرف تالت بيحتاج عقد/صلاحية من فوري.', manual: 'ادفع الكود من فوري أو محفظتك، وبعدين سجّل رقم العملية والإيصال هنا.' },
  credit: { label: 'التحقق من تسميع كود معيّن', reason: 'مفيش دليل رسمي بيربط كود فوري معيّن بزيادة الرصيد في الحساب الإعلاني — زيادة الرصيد وحدها مش إثبات (الإنفاق بيحركها كمان).', manual: 'راجع Ads Manager ← الفوترة ← المعاملات، وأكّد التسميع يدويًا بإدخال دليل.' },
};

export function providerStatus() {
  const simulation = simulationAllowed();
  const one = (kind) => {
    if (simulation) return { kind, mode: 'SIMULATION', available: true, status: 'محاكاة', label: NEEDS[kind].label, note: 'وضع اختبار على قاعدة بيانات الاختبار فقط — مفيش أكواد حقيقية ولا فلوس حقيقية.' };
    if (registry[kind]) return { kind, mode: 'REAL', available: true, status: 'متصل', label: NEEDS[kind].label };
    return { kind, mode: 'MANUAL', available: false, status: 'تحتاج ربط', label: NEEDS[kind].label, reason: NEEDS[kind].reason, manualPath: NEEDS[kind].manual };
  };
  return { simulation, extract: one('extract'), pay: one('pay'), credit: one('credit') };
}

// ---------------------------------------------------------------------------
// simulation
// ---------------------------------------------------------------------------
export const sim = { behavior: {}, paid: new Map(), creditDelayMs: 4000 };
const digits = (n) => Array.from(crypto.randomBytes(n), (b) => b % 10).join('');
const simAdapter = {
  async extract({ accountId, amountEgp, idempotencyKey }) {
    if (sim.behavior.extract) return sim.behavior.extract({ accountId, amountEgp, idempotencyKey });
    return { outcome: 'ISSUED', code: '9' + digits(9), expiresAt: new Date(Date.now() + 24 * 3_600_000).toISOString(), simulated: true };
  },
  async pay({ code, amountEgp, method, idempotencyKey }) {
    if (sim.behavior.pay) return sim.behavior.pay({ code, amountEgp, method, idempotencyKey });
    const prior = sim.paid.get(idempotencyKey); if (prior) return prior; // the same idempotency key never charges twice
    const res = { outcome: 'CONFIRMED', txnRef: 'SIM-' + digits(8), receipt: { number: 'SIM-R-' + digits(6), note: 'إيصال محاكاة — مش إيصال حقيقي' }, paidAt: new Date().toISOString(), amountEgp, simulated: true };
    sim.paid.set(idempotencyKey, res); return res;
  },
  async queryPayment({ idempotencyKey }) {
    if (sim.behavior.queryPayment) return sim.behavior.queryPayment({ idempotencyKey });
    const p = sim.paid.get(idempotencyKey); return p ? { outcome: 'CONFIRMED', txnRef: p.txnRef, receipt: p.receipt, paidAt: p.paidAt } : { outcome: 'UNKNOWN' };
  },
  async queryCredit({ code, paidAt }) {
    if (sim.behavior.queryCredit) return sim.behavior.queryCredit({ code, paidAt });
    const age = Date.now() - new Date(paidAt || 0).getTime();
    return age >= sim.creditDelayMs ? { outcome: 'CREDITED', source: 'SIMULATED', evidence: 'تسميع محاكاة', at: new Date().toISOString() } : { outcome: 'NOT_YET' };
  },
};

/** The adapter the engine talks to, or null when none is connected (the engine then offers the manual path). */
export function adapter(kind) {
  if (simulationAllowed()) return { ...simAdapter, simulated: true };
  return registry[kind] ? { ...registry[kind], simulated: false } : null;
}
